advanced.custom_css:
/* Kaya cart drawer - cartx Custom CSS
   Source design: Figma "Kaya" cart (file nSYH0a84mREw7hkZwpywL9), mobile
   frames "Cart" (empty), "Cart 2" (full cart) and "Cart 3" (fixed footer),
   360px wide. The drawer is 420px on desktop (full width on phones), so
   widths that track the frame are relative, not fixed.
   Colours, texts, milestone dots, coupon entry and upsell layout come from
   Customize Cart settings (kaya-cart-settings.json). This file holds what
   settings don't cover: the Montserrat/Poppins type scale, the two-line
   header with a cart icon, amounts above the milestone track, all cart lines
   in one card, the mint freebies block, recommendation cards, the coupon
   pill, the footer layout and the trust row.
   This is the same text as advanced.custom_css in the settings JSON. Icons
   are small inline SVG data URIs, so nothing needs to be uploaded. */

#cartmax-root .cartmax-drawer {
  --ky-ink: #262626;
  --ky-ink-2: #1E1F24;
  --ky-grey: #62636C;
  --ky-teal: #00A08C;
  --ky-line: #D8D9E0;
  --ky-divider: #E9E9E9;
  --ky-card-border: #F3F3F5;
  --ky-compare: #BDB3B3;
  --ky-red: #D13415;
  --ky-poppins: 'Poppins', var(--cartmax-font-family, sans-serif);
  --cartmax-img-size: 80px;
  color: var(--ky-ink);
}

/* ---------- Header: cart icon, "My Cart" over "2 Products" ---------- */
#cartmax-root .cartmax-header {
  height: 64px;
  min-height: 64px;
  padding: 0 4px 0 16px;
  border-bottom: 0;
}
#cartmax-root .cartmax-title {
  display: grid;
  grid-template-columns: 21px auto;
  column-gap: 12px;
  align-items: center;
  font-size: 16px;
  line-height: 24px;
  font-weight: 700;
  letter-spacing: -0.1px;
  color: var(--ky-ink);
  text-transform: none;
}
#cartmax-root .cartmax-title::before {
  content: "";
  grid-row: 1 / 3;
  grid-column: 1;
  width: 21px;
  height: 20px;
  background: url("data:image/svg+xml,%3Csvg width='21' height='20' viewBox='0 0 21 20' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 1H4L5 11H17L19 4H8' stroke-width='1.5' stroke='%23262626'/%3E%3Cpath d='M8 17C8 18.1046 7.10457 19 6 19C4.89543 19 4 18.1046 4 17C4 15.8954 4.89543 15 6 15C7.10457 15 8 15.8954 8 17Z' stroke-width='1.5' stroke='%23262626'/%3E%3Cpath d='M18 17C18 18.1046 17.1046 19 16 19C14.8954 19 14 18.1046 14 17C14 15.8954 14.8954 15 16 15C17.1046 15 18 15.8954 18 17Z' stroke-width='1.5' stroke='%23262626'/%3E%3C/svg%3E") center / contain no-repeat;
}
#cartmax-root .cartmax-header-count,
#cartmax-root .cartmax-title:not(:has(.cartmax-header-count))::after {
  grid-row: 2;
  grid-column: 2;
  display: block;
  width: auto;
  min-width: 0;
  height: auto;
  margin: 0;
  padding: 0;
  white-space: nowrap;
  background: none;
  border-radius: 0;
  font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  letter-spacing: -0.1px;
  color: var(--ky-ink);
}
#cartmax-root .cartmax-header-count::after { content: " Products"; }
/* Empty cart: cartx hides the count at 0, the design shows "0 Products" */
#cartmax-root .cartmax-title:not(:has(.cartmax-header-count))::after { content: "0 Products"; }
#cartmax-root .cartmax-close {
  width: 44px;
  height: 44px;
  padding: 12px;
  border: 0;
  border-radius: 0;
  background: none;
  box-shadow: none;
  color: var(--ky-ink);
}
#cartmax-root .cartmax-close svg { width: 20px; height: 20px; }

/* ---------- Body order: progress, cart card, freebies, recommended, coupon ---------- */
#cartmax-root .cartmax-body { padding: 0; gap: 0; }
#cartmax-root .cartmax-body > .cartmax-freebies { order: 1; }
#cartmax-root .cartmax-body > .cartmax-upsells { order: 2; }
#cartmax-root .cartmax-body > .cartmax-coupons { order: 3; }
#cartmax-root .cartmax-body > .cartmax-claims { order: 4; }

/* ---------- Milestone bar: amounts above a thin track, rewards below ---------- */
#cartmax-root .cartmax-progress {
  padding: 0;
  margin: 0;
  background: none;
  border: 0;
  overflow: visible;
}
#cartmax-root .cartmax-progress-msg-wrap { display: none; }
/* In the 360px frame the track is 288px (72px narrower than the drawer),
   starts 12px off the left edge and ends at the last dot (x 84 / 180 / 276).
   Relative, so the dots keep that spacing at 420px on desktop and on any
   phone width. */
#cartmax-root .cartmax-progress-track {
  width: calc(100% - 72px);
  height: 3px;
  margin: 46px 0 80px -12px;
  border-radius: 0;
}
#cartmax-root .cartmax-progress-fill { border-radius: 0; }
#cartmax-root .cartmax-milestone-dot,
#cartmax-root .cartmax-milestone--active .cartmax-milestone-dot,
#cartmax-root .cartmax-milestone--next .cartmax-milestone-dot {
  width: 24px;
  height: 24px;
  box-shadow: none;
}
#cartmax-root .cartmax-milestone-label,
#cartmax-root .cartmax-milestone--active .cartmax-milestone-label,
#cartmax-root .cartmax-milestone--next .cartmax-milestone-label {
  top: 30px;
  max-width: 96px;
  font-size: 10px;
  line-height: 14px;
  font-weight: 500;
  letter-spacing: 0;
  color: var(--ky-ink);
}
/* Only reached dots are teal; the next one keeps the locked look */
#cartmax-root .cartmax-milestone--next .cartmax-milestone-dot {
  background: #FFFFFF;
  border: 1px solid var(--ky-line);
}
#cartmax-root .cartmax-milestone-dot { border-width: 1px; }
#cartmax-root .cartmax-milestone--active .cartmax-milestone-dot { border-width: 0; }
/* The milestone amount (tier sub-label) is lifted above the track */
#cartmax-root .cartmax-milestone-sub-label,
#cartmax-root .cartmax-milestone--active .cartmax-milestone-sub-label,
#cartmax-root .cartmax-milestone--next .cartmax-milestone-sub-label {
  position: absolute;
  top: -58px;
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  white-space: nowrap;
  font-size: 14px;
  line-height: 20px;
  font-weight: 600;
  letter-spacing: 0.2px;
  color: var(--ky-ink-2);
}

/* ---------- Cart lines: one rounded, shadowed card ---------- */
#cartmax-root .cartmax-line-item:not(.cartmax-line-freebie) {
  position: relative;
  margin: 0 16px;
  padding: 12px;
  gap: 12px;
  background: #FFFFFF;
  border: 1px solid var(--ky-card-border);
  border-top: 0;
  border-bottom: 0;
  border-radius: 0;
  box-shadow: 0 0 12px rgba(0, 0, 0, 0.05);
  clip-path: inset(0 -12px);
}
/* first line in the card */
#cartmax-root .cartmax-line-item:not(.cartmax-line-freebie):not(.cartmax-line-item:not(.cartmax-line-freebie) ~ *) {
  border-top: 1px solid var(--ky-card-border);
  border-radius: 16px 16px 0 0;
  clip-path: inset(-12px -12px 0 -12px);
}
/* last line in the card */
#cartmax-root .cartmax-line-item:not(.cartmax-line-freebie):not(:has(~ .cartmax-line-item:not(.cartmax-line-freebie))) {
  border-bottom: 1px solid var(--ky-card-border);
  border-bottom-left-radius: 16px;
  border-bottom-right-radius: 16px;
  clip-path: inset(0 -12px -12px -12px);
  margin-bottom: 24px;
}
/* only line */
#cartmax-root .cartmax-line-item:not(.cartmax-line-freebie):not(.cartmax-line-item:not(.cartmax-line-freebie) ~ *):not(:has(~ .cartmax-line-item:not(.cartmax-line-freebie))) {
  clip-path: none;
}
/* divider between lines */
#cartmax-root .cartmax-line-item:not(.cartmax-line-freebie):has(~ .cartmax-line-item:not(.cartmax-line-freebie))::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 0;
  height: 1px;
  background: var(--ky-divider);
}
#cartmax-root .cartmax-line-image,
#cartmax-root .cartmax-line-image img {
  width: 80px;
  height: 80px;
  border-radius: 0;
  border: 0;
  background: transparent;
  object-fit: contain;
}
#cartmax-root .cartmax-line-title {
  font-size: 12px;
  line-height: 16px;
  font-weight: 500;
  letter-spacing: 0.6px;
  color: var(--ky-ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: block;
  -webkit-line-clamp: unset;
}
#cartmax-root .cartmax-line-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 2px;
}
#cartmax-root .cartmax-line-item:not(.cartmax-line-freebie) .cartmax-line-price > span:first-child {
  font-size: 14px;
  line-height: 21px;
  font-weight: 600;
  letter-spacing: 0.6px;
  color: rgba(38, 38, 38, 0.75);
}
#cartmax-root .cartmax-line-price-original {
  font-size: 14px;
  line-height: 18px;
  font-weight: 400;
  color: var(--ky-compare);
  text-decoration: line-through;
}
#cartmax-root .cartmax-line-savings-badge,
#cartmax-root .cartmax-line-discounts { display: none; }
#cartmax-root .cartmax-line-actions { margin-top: 8px; justify-content: flex-start; }
#cartmax-root .cartmax-qty-controls {
  width: 76px;
  height: 32px;
  margin-left: 0;
  padding: 0;
  justify-content: space-between;
  background: #FFFFFF;
  border: 0.93px solid #8B8B8B;
  border-radius: 7.42px;
}
#cartmax-root .cartmax-qty-btn {
  width: 24px;
  height: 30px;
  color: var(--ky-ink);
  background: none;
}
#cartmax-root .cartmax-qty-value {
  border: 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--ky-ink);
}
/* Remove: the "text" remove style, drawn as the grey bin beside the stepper */
#cartmax-root .cartmax-line-remove-text {
  position: absolute;
  right: 13px;
  bottom: 18px;
  width: 20px;
  height: 20px;
  padding: 0;
  font-size: 0;
  color: transparent;
  border: 0;
  background: url("data:image/svg+xml,%3Csvg width='20' height='20' viewBox='0 0 20 20' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M17.5 3.75H13.0875C13.0436 3.00415 12.7829 2.28733 12.3375 1.6875C11.8 1.025 11 0.625 10 0.625C9 0.625 8.2 1.025 7.6625 1.6875C7.2164 2.28698 6.95567 3.004 6.9125 3.75H2.5C2.33424 3.75 2.17527 3.81585 2.05806 3.93306C1.94085 4.05027 1.875 4.20924 1.875 4.375C1.875 4.54076 1.94085 4.69973 2.05806 4.81694C2.17527 4.93415 2.33424 5 2.5 5H4.0625V17.5C4.0625 17.85 4.3375 18.125 4.6875 18.125H15.3125C15.4783 18.125 15.6372 18.0592 15.7544 17.9419C15.8717 17.8247 15.9375 17.6658 15.9375 17.5V5H17.5C17.6658 5 17.8247 4.93415 17.9419 4.81694C18.0592 4.69973 18.125 4.54076 18.125 4.375C18.125 4.20924 18.0592 4.05027 17.9419 3.93306C17.8247 3.81585 17.6658 3.75 17.5 3.75ZM8.6375 2.475C8.925 2.1125 9.3625 1.875 10 1.875C10.6375 1.875 11.0625 2.1125 11.3625 2.475C11.6125 2.775 11.7375 3.225 11.8125 3.75H8.1875C8.25 3.225 8.4 2.775 8.6375 2.475ZM14.6875 16.875H5.3125V5H14.6875V16.875Z' fill='%23AFAFAF'/%3E%3Cpath d='M8.1875 6.5625C8.02174 6.5625 7.86277 6.62835 7.74556 6.74556C7.62835 6.86277 7.5625 7.02174 7.5625 7.1875V14.6875C7.5625 14.8533 7.62835 15.0122 7.74556 15.1294C7.86277 15.2467 8.02174 15.3125 8.1875 15.3125C8.35326 15.3125 8.51223 15.2467 8.62944 15.1294C8.74665 15.0122 8.8125 14.8533 8.8125 14.6875V7.1875C8.8125 7.02174 8.74665 6.86277 8.62944 6.74556C8.51223 6.62835 8.35326 6.5625 8.1875 6.5625ZM11.8125 6.5625C11.6467 6.5625 11.4878 6.62835 11.3706 6.74556C11.2533 6.86277 11.1875 7.02174 11.1875 7.1875V14.6875C11.1875 14.8533 11.2533 15.0122 11.3706 15.1294C11.4878 15.2467 11.6467 15.3125 11.8125 15.3125C11.9783 15.3125 12.1372 15.2467 12.2544 15.1294C12.3717 15.0122 12.4375 14.8533 12.4375 14.6875V7.1875C12.4375 7.02174 12.3717 6.86277 12.2544 6.74556C12.1372 6.62835 11.9783 6.5625 11.8125 6.5625Z' fill='%23AFAFAF'/%3E%3C/svg%3E") center / 20px 20px no-repeat;
}

/* ---------- Freebies For you: cartx Freebies section in a mint block ---------- */
#cartmax-root .cartmax-freebies {
  margin: 0 16px 24px;
  padding: 16px;
  border: 0;
  border-radius: 16px;
  background: linear-gradient(180deg, #DCFFFB 0%, #FFFFFF 100%);
}
#cartmax-root .cartmax-freebies-header {
  min-height: 24px;
  margin-bottom: 8px;
  padding: 0 0 16px 30px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.15);
  background: url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12 22C11.6 22 11.2167 21.925 10.85 21.775C10.4833 21.625 10.1583 21.4083 9.875 21.125C9.39167 20.6417 8.975 20.325 8.625 20.175C8.275 20.025 7.75 19.95 7.05 19.95C6.21667 19.95 5.50833 19.6583 4.925 19.075C4.34167 18.4917 4.05 17.7833 4.05 16.95C4.05 16.25 3.975 15.725 3.825 15.375C3.675 15.025 3.35833 14.6083 2.875 14.125C2.59167 13.8417 2.375 13.5167 2.225 13.15C2.075 12.7833 2 12.4 2 12C2 11.6 2.075 11.2167 2.225 10.85C2.375 10.4833 2.59167 10.1583 2.875 9.875C3.35833 9.39167 3.675 8.975 3.825 8.625C3.975 8.275 4.05 7.75 4.05 7.05C4.05 6.21667 4.34167 5.50833 4.925 4.925C5.50833 4.34167 6.21667 4.05 7.05 4.05C7.75 4.05 8.275 3.975 8.625 3.825C8.975 3.675 9.39167 3.35833 9.875 2.875C10.1583 2.59167 10.4833 2.375 10.85 2.225C11.2167 2.075 11.6 2 12 2C12.4 2 12.7833 2.075 13.15 2.225C13.5167 2.375 13.8417 2.59167 14.125 2.875C14.6083 3.35833 15.025 3.675 15.375 3.825C15.725 3.975 16.25 4.05 16.95 4.05C17.7833 4.05 18.4917 4.34167 19.075 4.925C19.6583 5.50833 19.95 6.21667 19.95 7.05C19.95 7.75 20.025 8.275 20.175 8.625C20.325 8.975 20.6417 9.39167 21.125 9.875C21.4083 10.1583 21.625 10.4833 21.775 10.85C21.925 11.2167 22 11.6 22 12C22 12.4 21.925 12.7833 21.775 13.15C21.625 13.5167 21.4083 13.8417 21.125 14.125C20.6417 14.6083 20.325 15.025 20.175 15.375C20.025 15.725 19.95 16.25 19.95 16.95C19.95 17.7833 19.6583 18.4917 19.075 19.075C18.4917 19.6583 17.7833 19.95 16.95 19.95C16.25 19.95 15.725 20.025 15.375 20.175C15.025 20.325 14.6083 20.6417 14.125 21.125C13.8417 21.4083 13.5167 21.625 13.15 21.775C12.7833 21.925 12.4 22 12 22ZM14.5 16C14.9167 16 15.2708 15.8542 15.5625 15.5625C15.8542 15.2708 16 14.9167 16 14.5C16 14.0833 15.8542 13.7292 15.5625 13.4375C15.2708 13.1458 14.9167 13 14.5 13C14.0833 13 13.7292 13.1458 13.4375 13.4375C13.1458 13.7292 13 14.0833 13 14.5C13 14.9167 13.1458 15.2708 13.4375 15.5625C13.7292 15.8542 14.0833 16 14.5 16ZM9.45 15.95L15.95 9.45L14.55 8.05L8.05 14.55L9.45 15.95ZM10.5625 10.5625C10.8542 10.2708 11 9.91667 11 9.5C11 9.08333 10.8542 8.72917 10.5625 8.4375C10.2708 8.14583 9.91667 8 9.5 8C9.08333 8 8.72917 8.14583 8.4375 8.4375C8.14583 8.72917 8 9.08333 8 9.5C8 9.91667 8.14583 10.2708 8.4375 10.5625C8.72917 10.8542 9.08333 11 9.5 11C9.91667 11 10.2708 10.8542 10.5625 10.5625Z' fill='%23000000'/%3E%3C/svg%3E") left top / 24px 24px no-repeat;
}
#cartmax-root .cartmax-freebies-title {
  font-size: 14px;
  line-height: 24px;
  font-weight: 600;
  color: var(--ky-ink-2);
}
#cartmax-root .cartmax-freebies-count {
  font-size: 12px;
  line-height: 24px;
  font-weight: 500;
  color: #62636C;
}
#cartmax-root .cartmax-freebies .cartmax-line-freebie,
#cartmax-root .cartmax-freebie-locked {
  margin: 0;
  padding: 8px 0;
  gap: 8px;
  border: 0;
  border-radius: 0;
  background: none;
}
#cartmax-root .cartmax-freebie-locked-img {
  border-radius: 6px;
  background: #FFFFFF;
}
#cartmax-root .cartmax-freebie-locked-title {
  font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  letter-spacing: 0.6px;
  color: var(--ky-ink-2);
}
#cartmax-root .cartmax-freebie-locked-msg {
  font-size: 14px;
  line-height: 20px;
  font-weight: 600;
  color: var(--ky-ink-2);
}

/* ---------- Header: mint "Clear All" pill ---------- */
#cartmax-root .cartmax-clear-all {
  padding: 5px 8px;
  border: 0;
  border-radius: 4px;
  background: #DDEDEB;
  font-size: 12px;
  line-height: 14px;
  font-weight: 600;
  color: var(--ky-ink-2);
}
#cartmax-root .cartmax-line-freebie .cartmax-line-image,
#cartmax-root .cartmax-line-freebie .cartmax-line-image img {
  width: 64px;
  height: 64px;
  border-radius: 6px;
  background: #FFFFFF;
}
#cartmax-root .cartmax-line-freebie .cartmax-line-title {
  font-weight: 400;
  white-space: normal;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
#cartmax-root .cartmax-line-freebie .cartmax-line-price { margin-top: 4px; gap: 4px; align-items: center; }
#cartmax-root .cartmax-line-freebie .cartmax-line-price-original {
  line-height: 20px;
  color: var(--ky-grey);
}
#cartmax-root .cartmax-gift-badge {
  display: inline-block;
  padding: 1px 4px;
  border-radius: 3px;
  background: var(--ky-teal);
  color: #FFFFFF;
  font-size: 12px;
  line-height: 16px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
}

/* ---------- Recommended For you ---------- */
#cartmax-root .cartmax-upsells {
  padding: 24px 0 36px 20px;
  margin: 0;
  background: none;
  border: 0;
}
#cartmax-root .cartmax-upsells-heading {
  margin: 0 0 12px;
  padding: 0;
  font-family: var(--ky-poppins);
  font-size: 16px;
  line-height: 24px;
  font-weight: 600;
  letter-spacing: -0.1px;
  color: var(--ky-ink-2);
  text-transform: none;
}
/* The drawer bleeds this row edge to edge with -20px side margins that
   cancel the container's padding. The container here only has left padding,
   so only the left margin is cancelled; otherwise the row is 20px wider than
   the drawer and the cart scrolls sideways. */
#cartmax-root .cartmax-upsells-scroll {
  gap: 20px;
  margin: 0 0 0 -20px;
  padding: 0 20px 8px 20px;
}
#cartmax-root .cartmax-upsell-card {
  flex: 0 0 240px;
  width: 240px;
  min-height: 84px;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  padding: 0;
  border: 0;
  background: none;
  box-shadow: none;
}
#cartmax-root .cartmax-upsell-media {
  position: relative;
  flex: 0 0 84px;
  width: 84px;
  height: 84px;
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow: visible;
}
#cartmax-root .cartmax-upsell-img {
  width: 84px;
  height: 84px;
  object-fit: contain;
}
#cartmax-root .cartmax-upsell-add {
  position: absolute;
  right: -4px;
  bottom: -4px;
  left: auto;
  top: auto;
  width: 32px;
  height: 32px;
  min-width: 0;
  padding: 0;
  font-size: 0;
  color: transparent;
  border: 1px solid #8B8B8B;
  border-radius: 6px;
