#cartmax-root .cartmax-upsell-info {
  flex: 1 1 auto;
  min-width: 0;
  padding: 0;
  text-align: left;
  align-items: flex-start;
}
#cartmax-root .cartmax-upsell-title {
  font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  letter-spacing: 0.6px;
  color: var(--ky-ink);
