#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-applied-card,
#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-discount-card--applied,
#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-discount-card-info {
  display: contents;
}
#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-coupon-link {
  grid-column: 2 / 4;
  grid-row: 2;
  width: auto;
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: none;
  justify-content: flex-start;
  gap: 6px;
}
#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-coupon-link-icon,
#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-coupon-link-subtitle,
