#cartmax-root .cartmax-applied-saved {
  grid-column: 2;
  grid-row: 1;
  margin: 0;
  padding: 0;
  background: none;
  font-family: var(--ky-poppins);
  font-size: 14px;
  line-height: 20px;
  font-weight: 600;
  letter-spacing: 0.2px;
  color: var(--ky-ink-2);
  white-space: nowrap;
}
#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-discount-card-code {
  grid-column: 3;
  grid-row: 1;
  justify-self: start;
  font-family: var(--ky-poppins);
  font-size: 14px;
  line-height: 20px;
  font-weight: 600;
  letter-spacing: 0.2px;
  color: var(--ky-ink-2);
  text-transform: uppercase;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#cartmax-root .cartmax-discount-block:has(.cartmax-applied-card) .cartmax-discount-card-code::before { content: "\2018"; }
