#cartmax-root .cartmax-discount-card-btn--remove {
  grid-column: 4;
  align-self: center;
  grid-row: 1 / 3;
  padding: 8px 12px;
  border: 1px solid #000000;
  border-radius: 99px;
  background: #FFFFFF;
  color: #000000;
  font-family: var(--ky-poppins);
  font-size: 12px;
  line-height: 16px;
  font-weight: 600;
  text-transform: none;
}

